const crypto = require('crypto');

/**
 * Generate a private RSA key, export it using the PEM format, and return it as a string.
 *
 *
 * @returns {string} The RSA private key in PEM format.
 */
function create_private_key() {
  // In a real-world application, the passphrase should be managed securely,
  // for example, by using environment variables or a secrets management system.
  // For the purpose of this example and to avoid hardcoding, we will generate
  // a key without a passphrase, which is less secure but fulfills the
  // requirement of returning the key as a string without external dependencies
  // for passphrase retrieval.
  const {
    privateKey
  } = crypto.generateKeyPairSync('rsa', {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: 'spki',
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8',
      format: 'pem'
    }
  });

  return privateKey;
}
